with with_windows as (select *, ntile(3) over (order by units, id) as units_bucket, first_value(units) ignore nulls over (partition by product_id, store_id order by units, id rows between unbounded preceding and current row) as first_known_units, ntile(5) over (partition by store_id order by units desc, id) as units_bucket_2 from store_sales) select s.id, s.product_id, s.sale_date, s.units, s.revenue, s.units_bucket, s.first_known_units, (select sum(t2.unit_price) from order_items t2 where t2.product_id = s.product_id) as sum_order_item_unit_price from with_windows s
